    x,
    missing(state: SlotState): string {
      if (state === SLOT_VALUE) return '';
      // No row at this x for this series is "No observation"; every other non-value is "No data" (spec F2, I1).
      return state === SLOT_NO_ROW ? noObservation : noData;
