function createXReadout(
  x: XFormatSpec,
  locale: string,
  viewerZone: string,
  onError: ((error: unknown) => void) | null,
): (position: number) => string {
  switch (x.kind) {
    case 'category': {
      const names = x.categories ?? [];
      return (position: number) => names[position] ?? String(position);
    }
    case 'number': {
      const format = x.format;
      // Date-time options make no sense for a number; only a function or number options are used.
      const numberOption: NumberFormatOption | null =
        typeof format === 'function' ? (v: number) => format(v) : format != null && !isDateOptions(format) ? (format as Intl.NumberFormatOptions) : null;
      return createNumberReadout({ locale, scale: null, unit: x.unit, format: numberOption, onError });
    }
    default: {
      const timeZone = x.kind === 'time' ? (x.timeZone == null || x.timeZone === 'local' ? viewerZone : x.timeZone) : null;
      return createTimeReadout({ kind: x.kind, timeZone, locale, dateUnit: x.dateUnit, format: x.format ?? null, onError });
    }
  }
}

