  let gapCount = 0;
  if (newStep) {
    last = previous.last;
    for (const row of rows) {
      const position = positions[row]!;
      if (last !== -Infinity) gapCount += stepMultiple(stepDelta(axis, last, position), newStep) - 1;
      last = position;
